{
  "sop_id": "SOP-017",
  "title": "Vendor Onboarding – Working Procedure",
  "steps": [
    {
      "step_id": "S1",
      "name": "Open and assign onboarding ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Collect registration form and statutory documents",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Check PAN, GSTIN, and MSME status on government portals",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Assess vendor capability and quality (questionnaire, references, certificates)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Assign risk category to vendor",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Confirm payment terms, NDA, and code-of-conduct acknowledgement",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Draft vendor master record",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S8",
      "name": "Submit vendor master record",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S9",
      "name": "Request Finance (Treasury) to validate bank account",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S10",
      "name": "Request Legal/Compliance for sanctions, blacklist, and conflict-of-interest screening",
      "role": "Executor",
      "type": "work"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "always"
    },
    {
      "stage": "HOD",
      "condition": "always"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Finance (Treasury)",
      "item": "Bank account validation",
      "parallel_group": "P1"
    },
    {
      "dep_id": "D2",
      "provider": "Legal/Compliance",
      "item": "Sanctions, blacklist, and conflict-of-interest screening",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.85
}
